// Generator timing
// 223: Max run time (0.1h)
// 224: Cooling time (0.1h)

msg.baseAddr = 223;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 223,
    quantity: 2
};
return msg;

// Generator charge
// 226: Start SOC (1%)
// 227: Charge current (1A)

msg.baseAddr = 226;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 226,
    quantity: 2
};
return msg;

// Charge enables
// 231: Generator charge enable
// 232: Grid charge enable

msg.baseAddr = 231;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 231,
    quantity: 2
};
return msg;

// Smart Load enable
// 235: generator input as load output enable
//      0=gen input, 1=smart load, 2=inverter input

msg.baseAddr = 235;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 235,
    quantity: 1
};
return msg;

// Smart Load SOC and PV thresholds
// 237: SmartLoad OFF batt (1%)
// 238: (skip)
// 239: SmartLoad ON batt (1%)
// 240: (skip)
// 241: minimum solar power (1W)

msg.baseAddr = 237;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 237,
    quantity: 5  // 237-241
};
return msg;

// Advanced function bits
// 280: Multiple bit fields
//   Bit 4-7: Gen peak shaving enable
//   Bit 12: On Grid always on

msg.baseAddr = 280;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 280,
    quantity: 1
};
return msg;

// Peak shaving power and delay
// 292: GEN peak shaving Power (1W)
// 293: (skip)
// 294: SmartLoad Open Delay (1 min)

msg.baseAddr = 292;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 292,
    quantity: 3  // 292-294
};
return msg;

// Build GeneratorAndSmartLoadConfigState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("GeneratorAndSmartLoadConfigState: missing base address");
    return null;
}

// ---- Store partials ----

// Gen Timing 223-224
if (baseAddr === 223) {
    flow.set("gsl_part_gen_timing", {
        maxRunTimeHours: Math.round((data[0] || 0) * 0.1 * 10) / 10,
        coolingTimeHours: Math.round((data[1] || 0) * 0.1 * 10) / 10
    });
}

// Gen Charge 226-227
else if (baseAddr === 226) {
    flow.set("gsl_part_gen_charge", {
        startSocPercent: data[0] || 0,
        chargeCurrentA: data[1] || 0
    });
}

// Enables 231-232
else if (baseAddr === 231) {
    flow.set("gsl_part_enables", {
        generatorChargeEnabled: (data[0] || 0) === 1,
        gridChargeEnabled: (data[1] || 0) === 1
    });
}

// SmartLoad Enable 235
else if (baseAddr === 235) {
    // 0=gen input, 1=smart load, 2=inverter input
    const mode = data[0] || 0;
    flow.set("gsl_part_smartload_enable", {
        smartLoadEnabled: mode === 1,
        smartLoadMode: mode
    });
}

// SmartLoad SOC/PV 237-241
else if (baseAddr === 237) {
    // data[0]=237, data[1]=238(skip), data[2]=239, data[3]=240(skip), data[4]=241
    flow.set("gsl_part_smartload_soc", {
        offSocPercent: data[0] || 0,      // 237
        onSocPercent: data[2] || 0,       // 239
        pvPowerThresholdW: data[4] || 0   // 241
    });
}

// Advanced Bits 280
else if (baseAddr === 280) {
    const bits = data[0] || 0;
    // Bit 4-7: Gen peak shaving (check if any of bits 4-7 set)
    const genPeakShavingEnabled = ((bits >> 4) & 0x0F) > 0;
    // Bit 12: On Grid always on
    const onGridAlwaysOn = ((bits >> 12) & 0x01) === 1;

    flow.set("gsl_part_adv_bits", {
        advBitsRaw: bits,
        genPeakShavingEnabled: genPeakShavingEnabled,
        onGridAlwaysOn: onGridAlwaysOn
    });
}

// Peak/Delay 292-294
else if (baseAddr === 292) {
    flow.set("gsl_part_peak_delay", {
        genPeakShavingPowerW: data[0] || 0,    // 292
        smartLoadOpenDelayMin: data[2] || 0    // 294
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const genTimingPart = flow.get("gsl_part_gen_timing");
const genChargePart = flow.get("gsl_part_gen_charge");
const enablesPart = flow.get("gsl_part_enables");
const slEnablePart = flow.get("gsl_part_smartload_enable");
const slSocPart = flow.get("gsl_part_smartload_soc");
const advBitsPart = flow.get("gsl_part_adv_bits");
const peakDelayPart = flow.get("gsl_part_peak_delay");

if (!genTimingPart || !genChargePart || !enablesPart || 
    !slEnablePart || !slSocPart || !advBitsPart || !peakDelayPart) {
    return null;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";

// Derive autoStartEnabled
const autoStartEnabled = enablesPart.generatorChargeEnabled && genChargePart.startSocPercent > 0;

const state = {
    kind: "GeneratorAndSmartLoadConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,
    version: "1",

    // A. Global battery-charge sources
    generatorChargeEnabled: enablesPart.generatorChargeEnabled,
    gridChargeEnabled: enablesPart.gridChargeEnabled,

    // B. Generator auto-start / auto-charge
    autoStartEnabled: autoStartEnabled,
    maxRunTimeHours: genTimingPart.maxRunTimeHours,
    coolingTimeHours: genTimingPart.coolingTimeHours,
    startSocPercent: genChargePart.startSocPercent,
    chargeCurrentA: genChargePart.chargeCurrentA,

    // C. Generator peak-shaving
    generatorPeakShaving: {
        enabled: advBitsPart.genPeakShavingEnabled,
        limitPowerW: peakDelayPart.genPeakShavingPowerW
    },

    // D. Smart-Load
    smartLoad: {
        enabled: slEnablePart.smartLoadEnabled,
        offSocPercent: slSocPart.offSocPercent,
        onSocPercent: slSocPart.onSocPercent,
        pvPowerThresholdW: slSocPart.pvPowerThresholdW,
        openDelayMinutes: peakDelayPart.smartLoadOpenDelayMin,
        onGridAlwaysOn: advBitsPart.onGridAlwaysOn
    },

    // Debug raw values
    _debug: {
        advBitsRaw: advBitsPart.advBitsRaw,
        smartLoadMode: slEnablePart.smartLoadMode
    }
};

// Clear partials
flow.set("gsl_part_gen_timing", null);
flow.set("gsl_part_gen_charge", null);
flow.set("gsl_part_enables", null);
flow.set("gsl_part_smartload_enable", null);
flow.set("gsl_part_smartload_soc", null);
flow.set("gsl_part_adv_bits", null);
flow.set("gsl_part_peak_delay", null);

flow.set("generatorSmartLoadConfigSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;
